    """Match a multi-segment wildcard '**' against arbitrary prefix of topic segments."""
    # Find the position of ** in pattern
    try:
        star_idx = pattern_segments.index("**")
    except ValueError:
        return False

    # Pattern before ** must match exactly
    prefix_len = star_idx
    if prefix_len > len(topic_segments):
        return False
    for i in range(prefix_len):
        if pattern_segments[i] != topic_segments[i]:
            return False

    # Everything after ** is ignored (matches arbitrary suffix)
    return True

